  ('curve-finance', 'Curve Finance', 'defi-systems-architecture', 'dexs-liquidity-protocols', 'https://curve.fi', ARRAY['Pool-based swaps executed fully onchain']::text[], ARRAY[]::text[], '{"description": "A specialized AMM optimized for stable and correlated assets, providing deep liquidity and minimal slippage near target prices.", "extras": {"Capital Efficiency Design Concentrated liquidity ranges (v3); uniform liquidity (v2)": "Highly capital-efficient stableswap invariants", "DEX Model Concentrated Liquidity AMM (v3); Constant Product AMM (v2 legacy)": "Stable / invariant-based AMM", "Dependency Concentration Risk High reliance by downstream protocols; High LP concentration risk in key pools; High MEV exposure by design": "High dependence on a few major stablecoins/LSTs; High reliance by downstream protocols", "Fee Control Fee tiers are protocol-defined; fee switches and new parameters are governance-controlled (not all activated)": "Governance-set fees and gauge emissions", "Governance Model DAO token governance (UNI)": "DAO token governance (CRV)", "Historical Stress Behavior Proven resilience through volatility events (2020–2024); stress typically expresses as fee spikes and LP reallocation, not protocol failure": "Proven through multiple depeg cycles (USDC 2023, others); stress shows as pool imbalance, not protocol failure", "Integration Footprint Lending liquidations, yield strategies, derivatives pricing, oracle references, treasury swaps": "Lending liquidations, stablecoin pegs, LST pricing, yield strategies", "Launch Year 2018 (v1); v2 2020; v3 2021": "2020", "Liquidity Providers Permissionless LPs": "Permissionless LPs; DAO-directed liquidity via gauges", "MEV Exposure Profile High (classic AMM MEV exposure: sandwiching, arbitrage)": "Medium (lower toxic MEV due to low volatility pairs; still arb-driven)", "Maintaining Organization Uniswap DAO (governance) with development by Uniswap Labs": "Curve DAO (CRV governance) with Curve core contributors", "Oracle Usage Native price output widely used externally (TWAPs referenced by oracles, lending, and derivatives)": "Native prices heavily referenced for stablecoins and LSTs (de facto peg oracle)", "Practitioner Validation Check YES executes trades onchain • YES sets prices via AMM curves • YES non-custodial settlement": "YES executes trades onchain • YES sets prices via AMM • YES non-custodial settlement", "Practitioner’s Note Key diligence: LP risk is non-trivial in v3 (range management, active rebalancing). Watch MEV exposure, LP concentration in narrow ranges, and dependency risk where Uniswap TWAPs act as de facto oracles.": "Key diligence: peg defense relies on LP depth and incentives; gauge politics affect liquidity placement; depeg events test pool resilience more than smart contracts.", "Price Discovery Method Continuous onchain pricing via AMM curves": "Continuous onchain pricing optimized for low-slippage around peg", "Primary Trading Pairs ETH pairs, stablecoin pairs, LST pairs, long-tail ERC-20s": "Stablecoin pairs, LST pairs, correlated assets (e.g., ETH/LST)", "Protocol Status Active (v3 dominant on Ethereum)": "Active (Ethereum mainnet core; multi-chain deployments)", "Reason for Inclusion Meets criteria: executes swaps onchain, defines its own pricing mechanism, and is a primary source of spot price discovery on Ethereum.": "Meets criteria: executes swaps onchain, defines pricing via invariant math, and is a primary price discovery venue for stablecoins and LSTs.", "Systemic Importance Very High (arguably the most systemically important spot DEX on Ethereum)": "Very High (critical for stablecoin and LST pricing across Ethereum DeFi)"}, "source_label": "DEXs & Liquidity Protocols"}'::jsonb),
  ('maverick-protocol', 'Maverick Protocol', 'defi-systems-architecture', 'dexs-liquidity-protocols', 'https://www.mav.xyz', ARRAY['Pool-based swaps with automatic liquidity movement']::text[], ARRAY[]::text[], '{"description": "A next-generation AMM where liquidity automatically shifts directionally with price, reducing LP management overhead and adverse selection.", "extras": {"Capital Efficiency Design Concentrated liquidity ranges (v3); uniform liquidity (v2)": "Dynamic liquidity that repositions with price moves", "DEX Model Concentrated Liquidity AMM (v3); Constant Product AMM (v2 legacy)": "Dynamic / directional AMM", "Dependency Concentration Risk High reliance by downstream protocols; High LP concentration risk in key pools; High MEV exposure by design": "Medium LP sophistication concentration; adoption/liquidity depth risk", "Fee Control Fee tiers are protocol-defined; fee switches and new parameters are governance-controlled (not all activated)": "Governance-configurable fees and pool parameters", "Governance Model DAO token governance (UNI)": "DAO governance (MAV)", "Historical Stress Behavior Proven resilience through volatility events (2020–2024); stress typically expresses as fee spikes and LP reallocation, not protocol failure": "Limited long-cycle stress history; monitor behavior during sharp trend reversals", "Integration Footprint Lending liquidations, yield strategies, derivatives pricing, oracle references, treasury swaps": "Emerging integrations; used by sophisticated LPs seeking efficiency", "Launch Year 2018 (v1); v2 2020; v3 2021": "2023", "Liquidity Providers Permissionless LPs": "Permissionless LPs", "MEV Exposure Profile High (classic AMM MEV exposure: sandwiching, arbitrage)": "Medium (design aims to reduce LP adverse selection vs static AMMs)", "Maintaining Organization Uniswap DAO (governance) with development by Uniswap Labs": "Maverick DAO / Maverick team (protocol governance and development)", "Oracle Usage Native price output widely used externally (TWAPs referenced by oracles, lending, and derivatives)": "Internal pricing only; not widely used as a canonical oracle", "Practitioner Validation Check YES executes trades onchain • YES sets prices via AMM curves • YES non-custodial settlement": "YES executes trades onchain • YES sets prices via AMM • YES non-custodial settlement", "Practitioner’s Note Key diligence: LP risk is non-trivial in v3 (range management, active rebalancing). Watch MEV exposure, LP concentration in narrow ranges, and dependency risk where Uniswap TWAPs act as de facto oracles.": "Key diligence: understand directional modes and LP exposure profiles; liquidity can concentrate rapidly, changing depth characteristics during volatility.", "Price Discovery Method Continuous onchain pricing via AMM curves": "Continuous onchain pricing with liquidity that follows price", "Primary Trading Pairs ETH pairs, stablecoin pairs, LST pairs, long-tail ERC-20s": "ETH pairs, stablecoin pairs, volatile assets", "Protocol Status Active (v3 dominant on Ethereum)": "Active", "Reason for Inclusion Meets criteria: executes swaps onchain, defines its own pricing mechanism, and is a primary source of spot price discovery on Ethereum.": "Meets criteria: executes swaps onchain, owns pricing/execution logic, and contributes to spot price discovery for supported pairs.", "Systemic Importance Very High (arguably the most systemically important spot DEX on Ethereum)": "Medium (innovative design, but not a primary system price anchor yet)"}, "source_label": "DEXs & Liquidity Protocols"}'::jsonb),
  ('dydx-v3-on-ethereum', 'dYdX (v3 on Ethereum)', 'defi-systems-architecture', 'dexs-liquidity-protocols', 'https://dydx.exchange', ARRAY['Onchain settlement with offchain order matching (v3 hybrid)']::text[], ARRAY[]::text[], '{"description": "A hybrid DEX that historically executed and settled trades on Ethereum using an order book model, contributing to price discovery via matched trades.", "extras": {"Capital Efficiency Design Concentrated liquidity ranges (v3); uniform liquidity (v2)": "Margin-efficient, order-book execution", "DEX Model Concentrated Liquidity AMM (v3); Constant Product AMM (v2 legacy)": "Order book–style perpetual DEX (spot execution context historically on Ethereum)", "Dependency Concentration Risk High reliance by downstream protocols; High LP concentration risk in key pools; High MEV exposure by design": "High reliance on market makers; Medium oracle and ops dependency", "Fee Control Fee tiers are protocol-defined; fee switches and new parameters are governance-controlled (not all activated)": "Governance-set fees and parameters", "Governance Model DAO token governance (UNI)": "DAO governance (DYDX)", "Historical Stress Behavior Proven resilience through volatility events (2020–2024); stress typically expresses as fee spikes and LP reallocation, not protocol failure": "Operated through high-volatility periods without AMM-style LP failures; migration reflects scaling tradeoffs", "Integration Footprint Lending liquidations, yield strategies, derivatives pricing, oracle references, treasury swaps": "Reference architecture for hybrid onchain DEX design; historical integrations", "Liquidity Providers Permissionless LPs": "Professional market makers (permissioned in v3 era)", "MEV Exposure Profile High (classic AMM MEV exposure: sandwiching, arbitrage)": "Medium (hybrid design reduced some AMM MEV vectors)", "Maintaining Organization Uniswap DAO (governance) with development by Uniswap Labs": "dYdX Trading Inc. with governance by dYdX DAO", "Oracle Usage Native price output widely used externally (TWAPs referenced by oracles, lending, and derivatives)": "Uses external oracles for pricing/settlement checks", "Practitioner Validation Check YES executes trades onchain • YES sets prices via AMM curves • YES non-custodial settlement": "YES executed trades settled on Ethereum (v3) • YES prices set via matched trades • YES non-custodial settlement at the protocol layer", "Practitioner’s Note Key diligence: LP risk is non-trivial in v3 (range management, active rebalancing). Watch MEV exposure, LP concentration in narrow ranges, and dependency risk where Uniswap TWAPs act as de facto oracles.": "Context matters: include only the Ethereum v3 era. Useful as a reference for hybrid designs; exclude current app-chain operations when analyzing Ethereum-native liquidity today.", "Price Discovery Method Continuous onchain pricing via AMM curves": "Order book price discovery anchored by onchain settlement", "Primary Trading Pairs ETH pairs, stablecoin pairs, LST pairs, long-tail ERC-20s": "ETH and major ERC-20 pairs (perps context; spot execution historically present)", "Protocol Status Active (v3 dominant on Ethereum)": "Deprecated on Ethereum (migrated to app-chain later)", "Reason for Inclusion Meets criteria: executes swaps onchain, defines its own pricing mechanism, and is a primary source of spot price discovery on Ethereum.": "Included for historical Ethereum DEX execution: owned execution logic, settled onchain, and contributed to price discovery during its Ethereum-native phase.", "Systemic Importance Very High (arguably the most systemically important spot DEX on Ethereum)": "Medium (historical)"}, "source_label": "DEXs & Liquidity Protocols"}'::jsonb),
  ('0x-protocol', '0x Protocol', 'defi-systems-architecture', 'dexs-liquidity-protocols', 'https://0x.org', ARRAY['Onchain settlement of RFQ and limit orders']::text[], ARRAY[]::text[], '{"description": "A DEX protocol enabling onchain settlement of RFQ and limit orders, where prices are quoted by market makers and executed trustlessly on Ethereum.", "extras": {"Capital Efficiency Design Concentrated liquidity ranges (v3); uniform liquidity (v2)": "Capital-efficient RFQ fills (no passive LP capital)", "DEX Model Concentrated Liquidity AMM (v3); Constant Product AMM (v2 legacy)": "RFQ / Hybrid onchain execution protocol", "Dependency Concentration Risk High reliance by downstream protocols; High LP concentration risk in key pools; High MEV exposure by design": "High MM concentration risk; Medium dependency on integrators’ flow", "Fee Control Fee tiers are protocol-defined; fee switches and new parameters are governance-controlled (not all activated)": "Governance-controlled fees (varies by deployment)", "Governance Model DAO token governance (UNI)": "DAO governance (ZRX)", "Historical Stress Behavior Proven resilience through volatility events (2020–2024); stress typically expresses as fee spikes and LP reallocation, not protocol failure": "Resilient; stress shows as liquidity withdrawal by MMs rather than protocol failure", "Integration Footprint Lending liquidations, yield strategies, derivatives pricing, oracle references, treasury swaps": "Widely embedded in wallets, dApps, and institutional flows", "Launch Year 2018 (v1); v2 2020; v3 2021": "2017", "Liquidity Providers Permissionless LPs": "Professional market makers (RFQ)", "MEV Exposure Profile High (classic AMM MEV exposure: sandwiching, arbitrage)": "Low–Medium (RFQ reduces sandwich risk)", "Maintaining Organization Uniswap DAO (governance) with development by Uniswap Labs": "0x DAO with development by 0x Labs", "Oracle Usage Native price output widely used externally (TWAPs referenced by oracles, lending, and derivatives)": "Limited oracle dependence; prices set by quotes", "Practitioner Validation Check YES executes trades onchain • YES sets prices via AMM curves • YES non-custodial settlement": "YES settles trades onchain • YES prices set via quotes executed onchain • YES non-custodial settlement", "Practitioner’s Note Key diligence: LP risk is non-trivial in v3 (range management, active rebalancing). Watch MEV exposure, LP concentration in narrow ranges, and dependency risk where Uniswap TWAPs act as de facto oracles.": "Scope carefully: include RFQ/onchain fills; exclude pure routing/aggregation use. Key value is MEV-resistant execution for large trades.", "Price Discovery Method Continuous onchain pricing via AMM curves": "Quote-driven price discovery settled onchain", "Primary Trading Pairs ETH pairs, stablecoin pairs, LST pairs, long-tail ERC-20s": "Major ERC-20 pairs; stablecoin pairs", "Protocol Status Active (v3 dominant on Ethereum)": "Active", "Reason for Inclusion Meets criteria: executes swaps onchain, defines its own pricing mechanism, and is a primary source of spot price discovery on Ethereum.": "Included when used for onchain execution: it owns settlement logic and sets prices via onchain trades (RFQ fills), not merely routing.", "Systemic Importance Very High (arguably the most systemically important spot DEX on Ethereum)": "High (infrastructure-level importance; execution layer for many apps)"}, "source_label": "DEXs & Liquidity Protocols"}'::jsonb),
  ('cow-protocol', 'Cow Protocol', 'defi-systems-architecture', 'dexs-liquidity-protocols', 'https://cow.fi', ARRAY['Batch auctions settled onchain via a settlement contract', 'solver competition']::text[], ARRAY[]::text[], '{"description": "A DEX that batches trades and clears them at a uniform price, leveraging solver competition to minimize MEV and improve execution.", "extras": {"Capital Efficiency Design Concentrated liquidity ranges (v3); uniform liquidity (v2)": "Capital-efficient via netting and coincidence-of-wants", "DEX Model Concentrated Liquidity AMM (v3); Constant Product AMM (v2 legacy)": "Batch auction / RFQ hybrid", "Dependency Concentration Risk High reliance by downstream protocols; High LP concentration risk in key pools; High MEV exposure by design": "Medium solver concentration risk; Medium dependency on underlying AMM liquidity for fallback", "Fee Control Fee tiers are protocol-defined; fee switches and new parameters are governance-controlled (not all activated)": "Governance-set protocol fees", "Governance Model DAO token governance (UNI)": "DAO governance (COW)", "Historical Stress Behavior Proven resilience through volatility events (2020–2024); stress typically expresses as fee spikes and LP reallocation, not protocol failure": "Resilient during volatility; stress shows as higher reliance on AMM fallback rather than failed settlement", "Integration Footprint Lending liquidations, yield strategies, derivatives pricing, oracle references, treasury swaps": "Wallet integrations, DAO treasury trades, institutional-sized swaps", "Launch Year 2018 (v1); v2 2020; v3 2021": "2021", "Liquidity Providers Permissionless LPs": "Professional solvers + AMM liquidity as fallback", "MEV Exposure Profile High (classic AMM MEV exposure: sandwiching, arbitrage)": "Low (designed to minimize MEV via batch auctions)", "Maintaining Organization Uniswap DAO (governance) with development by Uniswap Labs": "Cow DAO (Gnosis ecosystem)", "Oracle Usage Native price output widely used externally (TWAPs referenced by oracles, lending, and derivatives)": "Limited oracle dependence; prices emerge from auction clearing", "Practitioner Validation Check YES executes trades onchain • YES sets prices via AMM curves • YES non-custodial settlement": "YES executes trades onchain • YES sets prices via batch clearing • YES non-custodial settlement", "Practitioner’s Note Key diligence: LP risk is non-trivial in v3 (range management, active rebalancing). Watch MEV exposure, LP concentration in narrow ranges, and dependency risk where Uniswap TWAPs act as de facto oracles.": "Key diligence: solver set health and competition, fallback reliance on AMMs during thin auctions, and latency tradeoffs vs continuous AMMs.", "Price Discovery Method Continuous onchain pricing via AMM curves": "Uniform clearing price per batch (auction-based price discovery)", "Primary Trading Pairs ETH pairs, stablecoin pairs, LST pairs, long-tail ERC-20s": "Major ERC-20s; stablecoin pairs; ETH pairs", "Protocol Status Active (v3 dominant on Ethereum)": "Active", "Reason for Inclusion Meets criteria: executes swaps onchain, defines its own pricing mechanism, and is a primary source of spot price discovery on Ethereum.": "Meets criteria: owns execution logic, settles trades onchain, and sets prices through auction clearing on Ethereum.", "Systemic Importance Very High (arguably the most systemically important spot DEX on Ethereum)": "High (critical MEV-resistant execution layer for large trades)"}, "source_label": "DEXs & Liquidity Protocols"}'::jsonb)
) AS v(slug, name, sector_slug, subsector_slug, website, chains, tags, meta)
JOIN public.sectors sec ON sec.slug = v.sector_slug
JOIN public.subsectors s ON s.sector_id = sec.id AND s.slug = v.subsector_slug
ON CONFLICT (slug) DO UPDATE SET
  name = EXCLUDED.name,
  subsector_id = EXCLUDED.subsector_id,
  website = EXCLUDED.website,
  chains = EXCLUDED.chains,
  tags = EXCLUDED.tags,
  meta = EXCLUDED.meta,
  updated_at = NOW();
